\begin{proposition}
\label{prop:extension-smooth-function}
\dcref{chA:A.23}
\uses{thm:local-embedding-theorem}
Suppose $\bar{M}$ is a smooth manifold and $M \subseteq \bar{M}$ is an
embedded submanifold. Every smooth function $f:M\to\mathbb{R}$ extends to a
smooth function on a neighborhood of $M$ in $\bar{M}$ whose restriction to
$M$ is $f$. If $M$ is closed in $\bar{M}$, the extension can be defined on all
of $\bar{M}$.
\end{proposition}

